INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Marketingunterlagen immer physisch sein müssen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch digital möglich"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Marketingunterlagen für eine IT-Firma erstelle?', 3, '[{"text": "Zielgruppenansprache", "correct": true, "because": "Sichert Relevanz"}, {"text": "Schnellste Fertigstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu Marketingunterlagen in der IT?', 5, '[{"text": "Produktbeschreibungen", "correct": true, "because": "Informieren Kunden"}, {"text": "Datenblätter", "correct": true, "because": "Technische Details"}, {"text": "Büromöbel", "correct": false, "because": "Kein Marketingfaktor"}, {"text": "Mitarbeiterfotos", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Marketingunterlagen fördern den Verkauf. b) Sie sind immer rechtlich bindend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht bindend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Marketingunterlagen für IT-Dienstleistungen erstelle?', 4, '[{"text": "Zielgruppenbedarf", "correct": false, "because": "Steuert Inhalt"}, {"text": "Produktvorteile", "correct": false, "because": "Fördert Verkauf"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marketingfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Marketingunterlagen nur für Kunden gedacht sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch intern nutzbar"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Marketingunterlagen in der IT?', 3, '[{"text": "Kundeninformation", "correct": true, "because": "Fördert Verkauf"}, {"text": "Schnellste Erstellung", "correct": false, "because": "Qualität wichtiger"}, {"text": "Weniger Inhalte", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile sind für Marketingunterlagen entscheidend?', 5, '[{"text": "Technische Spezifikationen", "correct": true, "because": "Informieren Kunden"}, {"text": "Nutzenversprechen", "correct": true, "because": "Überzeugt Kunden"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Mitarbeiteranzahl", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Marketingunterlagen müssen ansprechend sein. b) Sie sind immer vertraulich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht vertraulich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Marketingunterlagen in der IT?', 4, '[{"text": "Kundennutzen", "correct": false, "because": "Fördert Interesse"}, {"text": "Produktmerkmale", "correct": false, "because": "Wichtig für Verkauf"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marketingfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Marketingunterlagen immer physische Broschüren?', 2, '[{"text": "Nein", "correct": true, "because": "Auch digital möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Marketingunterlagen für IT-Dienstleistungen?', 4, '[{"text": "Kundengewinnung", "correct": true, "because": "Fördert Interesse"}, {"text": "Markenbekanntheit", "correct": true, "because": "Stärkt Image"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Marketingunterlagen nur für große Firmen wichtig sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für KMU relevant"}, {"text": "Ja", "correct": false, "because": "Für alle nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Marketingunterlagen für IT-Produkte zu erstellen?', 3, '[{"text": "Zielgruppenanalyse", "correct": true, "because": "Passt Inhalte an"}, {"text": "Schnellste Software", "correct": false, "because": "Qualität wichtiger"}, {"text": "Bunte Layouts", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Marketingunterlagen informieren über Produkte. b) Sie sind immer vertraulich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Öffentlich zugänglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Marketingunterlagen für IT?', 5, '[{"text": "Kundenbedürfnisse", "correct": true, "because": "Steuern Inhalt"}, {"text": "Produktvorteile", "correct": true, "because": "Fördern Verkauf"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Marketingunterlagen für IT-Dienstleistungen erstelle?', 3, '[{"text": "Technische Details", "correct": false, "because": "Informieren Kunden"}, {"text": "Klarheit", "correct": false, "because": "Sichert Verständnis"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marketingfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen Marketingunterlagen immer gedruckt sein?', 3, '[{"text": "Nein", "correct": true, "because": "Auch digital effektiv"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Marketingunterlagen nur für neue Produkte wichtig sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für bestehende"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
